insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('2225d2da-8903-4c62-a089-7f73a73652c0', '14d547af-2264-41e5-9b8a-cc23a9aa39d6', $$driehoek ABC met AB = 4, BC = 12 en zwaartelijn AM = 5$$,
   $$wiskunde-b-vwo-2021-iii-onbekende-zijde-context1.png$$,
   $$Gegeven is driehoek ABC met AB = 4 en BC = 12.
Punt M is het midden van lijnstuk BC. Verder geldt: AM = 5$$, 'inline'),
  ('f2dfe897-4c9f-4e92-9968-75593f19702c', 'a9356d64-e544-400a-8696-29a985f9efb4', $$functies f(x) = sin(x)cos(2x) en g(x) = 2 + sin(x) op [−½π, 1½π]$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context1.png$$,
   $$Op het domein [−½π, 1½π] worden de functies f en g gegeven door:
f(x) = sin(x)cos(2x)
g(x) = 2 + sin(x)$$, 'inline'),
  ('da64edf4-8e0c-4b8d-a8d8-2a2c2af5a095', 'a9356d64-e544-400a-8696-29a985f9efb4', $$afgeleide f′(x) = 6cos³(x) − 5cos(x)$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context2.png$$,
   $$Er geldt: f′(x) = 6cos³(x) − 5cos(x).$$, 'inline'),
  ('0c5f4372-0ef0-4631-8356-674137e5568b', 'a9356d64-e544-400a-8696-29a985f9efb4', $$verticale lijn x = p, punten A en B en de raaklijnen in A en B$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context3.png$$,
   $$In de figuur zijn de grafieken van f en g weergegeven. De verticale lijn met vergelijking x = p snijdt de grafiek van f in het punt A en de grafiek van g in het punt B. We bekijken de raaklijn aan de grafiek van f in A en de raaklijn aan de grafiek van g in B.$$, 'inline'),
  ('bb9f67d3-082e-4484-8c9f-47cfe171f170', 'a9356d64-e544-400a-8696-29a985f9efb4', $$figuur: grafieken van f en g met de raaklijnen in A en B$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context4.png$$,
   $$figuur: de grafieken van f en g met de verticale lijn x = p en de raaklijnen in A en B$$, 'inline'),
  ('65da860c-84d5-4e17-bcb0-f4819394d249', 'a9356d64-e544-400a-8696-29a985f9efb4', $$de twee raaklijnen snijden elkaar loodrecht$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context5.png$$,
   $$In de figuur is een waarde van p gekozen waarvoor de twee raaklijnen elkaar loodrecht snijden. Er zijn meerdere waarden van p waarvoor dit het geval is.$$, 'inline'),
  ('8040648e-7517-44d4-897b-44fff1d47edc', 'a9356d64-e544-400a-8696-29a985f9efb4', $$herleiding f(x) = ½(sin(3x) − sin(x))$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context6.png$$,
   $$Het functievoorschrift van f kan worden herleid tot:
f(x) = ½(sin(3x) − sin(x))$$, 'inline'),
  ('51e64549-facf-4a12-9c4b-b1e5f61114e0', 'a9356d64-e544-400a-8696-29a985f9efb4', $$hint: herleid sin(t + u) − sin(t − u)$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context7.png$$,
   $$Dit kan bijvoorbeeld worden bewezen door de vorm sin(t + u) − sin(t − u) voor een geschikte keuze van t en u te herleiden.$$, 'inline'),
  ('00e23a14-4f75-40e3-a5d6-44e56c82c495', 'a9356d64-e544-400a-8696-29a985f9efb4', $$gemeenschappelijke punten (−½π, 1) en (1½π, 1)$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context8.png$$,
   $$De grafieken van f en g hebben twee gemeenschappelijke punten, namelijk (−½π, 1) en (1½π, 1).$$, 'inline'),
  ('438e34d0-1712-4709-8fa9-2d771c4ebd9e', 'a9356d64-e544-400a-8696-29a985f9efb4', $$gebied V ingesloten door de grafieken van f en g$$,
   $$wiskunde-b-vwo-2021-iii-spookje-context9.png$$,
   $$V is het gebied dat wordt ingesloten door de grafieken van f en g.$$, 'inline'),
  ('2b5b6c9c-9c9b-4e40-9e22-442325115fb9', '52414f21-f9cb-4ba2-b9b9-13f493db7a77', $$model C = a − b·ln(ln(T/(T − 1))) voor capaciteit en herhalingstijd (formule 1)$$,
   $$wiskunde-b-vwo-2021-iii-hoogwater-context1.png$$,
   $$De hoeveelheid water die door een rivier wordt afgevoerd, varieert van moment tot moment. De hoeveelheid water die de rivier maximaal kan afvoeren, noemen we de capaciteit van de rivier. Als de capaciteit te laag is, kan de rivier overstromen. Om te kunnen inschatten hoe vaak een overstroming plaatsvindt, gebruiken we het volgende model:
C = a − b · ln(ln(T/(T − 1))) met T > 1 (formule 1)
Hierin is C de capaciteit in m³/s en T de zogeheten herhalingstijd. De herhalingstijd is de periode in jaren waarin de waarde van C gemiddeld één keer wordt overschreden. Als bijvoorbeeld T = 40, dan zal de rivier gemiddeld één keer in de 40 jaar overstromen.
De waarden van a en b worden berekend met behulp van gegevens uit het verleden. Er geldt altijd: a > 0 en b > 0.$$, 'inline'),
  ('0fadf70d-d32e-4566-bc10-72ea8efc9e60', '52414f21-f9cb-4ba2-b9b9-13f493db7a77', $$Rijn: a = 5734, b = 1648, capaciteit 12000 m³/s$$,
   $$wiskunde-b-vwo-2021-iii-hoogwater-context2.png$$,
   $$Voor de Rijn geldt: a = 5734 en b = 1648. De capaciteit is 12000 m³/s.$$, 'inline'),
  ('4c354e4a-c0f0-4393-9011-c386b9c501c7', '52414f21-f9cb-4ba2-b9b9-13f493db7a77', $$formule 2: dC/dT = b/(T·(T − 1)·ln(T/(T − 1)))$$,
   $$wiskunde-b-vwo-2021-iii-hoogwater-context3.png$$,
   $$Uit formule 1 is af te leiden dat voor de afgeleide van C geldt:
dC/dT = b/(T · (T − 1) · ln(T/(T − 1))) met T > 1 (formule 2)$$, 'inline'),
  ('795772ca-9854-4e1d-87d4-2520886c0361', '52414f21-f9cb-4ba2-b9b9-13f493db7a77', $$de grafiek van C moet stijgend zijn$$,
   $$wiskunde-b-vwo-2021-iii-hoogwater-context4.png$$,
   $$Voor elke rivier geldt natuurlijk: hoe groter de herhalingstijd, des te groter is de capaciteit. De grafiek van C zou dus voor elke waarde van a en b (met a > 0 en b > 0) stijgend moeten zijn.$$, 'inline'),
  ('82d86528-b69c-4a99-843d-e629080d1c8c', '52414f21-f9cb-4ba2-b9b9-13f493db7a77', $$Maas: 1700 m³/s bij T = 4 en 2100 m³/s bij T = 10$$,
   $$wiskunde-b-vwo-2021-iii-hoogwater-context5.png$$,
   $$Voor de Maas geldt:
– Bij een capaciteit van 1700 m³/s is de herhalingstijd gelijk aan 4 jaar.
– Bij een capaciteit van 2100 m³/s is de herhalingstijd gelijk aan 10 jaar.$$, 'inline'),
  ('3adc33a8-181e-4c97-b7a9-990efc8aaf3f', '52414f21-f9cb-4ba2-b9b9-13f493db7a77', $$gevraagd: capaciteit van de Maas bij herhalingstijd 100 jaar$$,
   $$wiskunde-b-vwo-2021-iii-hoogwater-context6.png$$,
   $$Voor toekomstig beleid wil het ministerie van Infrastructuur en Waterstaat voor de Maas weten welke capaciteit hoort bij een herhalingstijd van 100 jaar$$, 'inline'),
  ('698d7b54-e6e9-4716-a856-e303ce7546f8', 'adac6a50-2450-4ddc-a3dd-b2c5355e8176', $$halve cirkels c₁: x² + y² + 12x = −32 en c₂ met middelpunt M₂(5,0) en straal 5$$,
   $$wiskunde-b-vwo-2021-iii-twee-halve-cirkels-context1.png$$,
   $$Gegeven zijn de twee halve cirkels c₁ en c₂.
Voor c₁ geldt: x² + y² + 12x = −32, het middelpunt is M₁ en y ≥ 0.
Voor c₂ geldt: het middelpunt is M₂(5,0), de straal is 5 en y ≥ 0.$$, 'inline'),
  ('e6bdffa0-b7cc-40e2-8c74-c0400e4a201d', 'adac6a50-2450-4ddc-a3dd-b2c5355e8176', $$punt P op de positieve y-as$$,
   $$wiskunde-b-vwo-2021-iii-twee-halve-cirkels-context2.png$$,
   $$Op de positieve y-as ligt een punt P. Zie de figuur.$$, 'inline'),
  ('64063087-4011-4368-a684-e03b74a25f26', 'adac6a50-2450-4ddc-a3dd-b2c5355e8176', $$figuur: halve cirkels c₁ en c₂ en punt P$$,
   $$wiskunde-b-vwo-2021-iii-twee-halve-cirkels-context3.png$$,
   $$figuur: de halve cirkels c₁ en c₂ met middelpunten M₁ en M₂ en het punt P op de y-as$$, 'inline'),
  ('fad06a5f-48be-4e98-b55d-afabbce0f824', 'adac6a50-2450-4ddc-a3dd-b2c5355e8176', $$afstand van P tot c₁ is twee keer de afstand van P tot c₂$$,
   $$wiskunde-b-vwo-2021-iii-twee-halve-cirkels-context4.png$$,
   $$P wordt zo op de y-as gekozen dat de afstand van P tot c₁ twee keer zo groot is als de afstand van P tot c₂.$$, 'inline'),
  ('90e656a2-483e-414f-980b-e4fe4df05408', 'b5be86cd-11aa-43cb-8f2c-c6efa10b987a', $$bewegingsvergelijkingen P₁: x(t) = t² + 2t, y(t) = 4t$$,
   $$wiskunde-b-vwo-2021-iii-twee-bewegende-punten-context1.png$$,
   $$Voor t ≥ 0 beweegt het punt P₁ volgens de bewegingsvergelijkingen:
x(t) = t² + 2t
y(t) = 4t$$, 'inline'),
  ('56ebcc04-904a-40b4-8df1-2ef90a60208f', 'b5be86cd-11aa-43cb-8f2c-c6efa10b987a', $$bewegingsvergelijkingen P₂: x(t) = 4t, y(t) = 2t²$$,
   $$wiskunde-b-vwo-2021-iii-twee-bewegende-punten-context2.png$$,
   $$Tegelijkertijd beweegt het punt P₂ volgens de bewegingsvergelijkingen:
x(t) = 4t
y(t) = 2t²$$, 'inline'),
  ('4ecc7128-717f-48be-b588-9004e95e31e5', 'b5be86cd-11aa-43cb-8f2c-c6efa10b987a', $$figuur 1 toont beide banen$$,
   $$wiskunde-b-vwo-2021-iii-twee-bewegende-punten-context3.png$$,
   $$In figuur 1 zijn beide banen getekend met daarop de punten P₁ en P₂ op een tijdstip t.$$, 'inline'),
  ('c78aad46-3fff-46d2-93d1-9c4a76a6e6aa', 'b5be86cd-11aa-43cb-8f2c-c6efa10b987a', $$figuur 1 en snelheid v₂(t) = 4√(t² + 1); gelijke snelheid op één tijdstip$$,
   $$wiskunde-b-vwo-2021-iii-twee-bewegende-punten-context4.png$$,
   $$figuur 1: de banen van P₁ en P₂
Voor de snelheid v₂ van P₂ geldt: v₂(t) = 4√(t² + 1).
Er is één tijdstip t waarop de punten P₁ en P₂ gelijke snelheid hebben.$$, 'inline'),
  ('8f18244b-6ca7-4b87-aeb2-11ca523b9a6e', 'b5be86cd-11aa-43cb-8f2c-c6efa10b987a', $$lijn l door P₁ en P₂ (P₁ en P₂ vallen samen voor t = 0 en t = 2)$$,
   $$wiskunde-b-vwo-2021-iii-twee-bewegende-punten-context5.png$$,
   $$In figuur 2 zijn nogmaals beide banen getekend.
Op twee tijdstippen, namelijk t = 0 en t = 2, vallen P₁ en P₂ samen. Op alle andere tijdstippen kun je de lijn l door P₁ en P₂ tekenen. In figuur 2 is dit voor twee tijdstippen gedaan.$$, 'inline'),
  ('43507082-cefe-4e80-9c07-538f0e13e347', 'b5be86cd-11aa-43cb-8f2c-c6efa10b987a', $$figuur 2 en: richtingscoëfficiënt van l is −2$$,
   $$wiskunde-b-vwo-2021-iii-twee-bewegende-punten-context6.png$$,
   $$figuur 2: de banen van P₁ en P₂ met de lijn l voor twee tijdstippen
De richtingscoëfficiënt van l is gelijk aan −2 voor elke waarde van t (met t ≠ 0 en t ≠ 2).$$, 'inline'),
  ('c651b4b2-e8bd-42c8-9a42-5ad58097f7d9', 'b5be86cd-11aa-43cb-8f2c-c6efa10b987a', $$P₃ is het snijpunt van l met de x-as$$,
   $$wiskunde-b-vwo-2021-iii-twee-bewegende-punten-context7.png$$,
   $$Voor elke waarde van t (met t ≠ 0 en t ≠ 2) is P₃ het snijpunt van l met de x-as. Zie figuur 2, waarin P₃ is aangegeven voor twee verschillende tijdstippen.$$, 'inline'),
  ('b06af1dd-00c2-404c-8e7e-c7f3da438496', '9d61d7f2-fa1a-4dc9-8b33-e21e03930ba3', $$functie f(x) = x³ + 6x² + 12x + 9 met inverse f^inv(x) = −2 + ∛(x − 1)$$,
   $$wiskunde-b-vwo-2021-iii-een-derdegraadsfunctie-context1.png$$,
   $$De functie f wordt gegeven door f(x) = x³ + 6x² + 12x + 9.
Deze functie heeft een inverse functie f^inv. Er geldt: f^inv(x) = −2 + ∛(x − 1).$$, 'inline'),
  ('0189b045-f76a-4d4c-94bc-f6c2b93c62a1', '9d61d7f2-fa1a-4dc9-8b33-e21e03930ba3', $$vlakdeel V ingesloten door de grafiek van f, de x-as en de y-as$$,
   $$wiskunde-b-vwo-2021-iii-een-derdegraadsfunctie-context2.png$$,
   $$V is het vlakdeel dat wordt ingesloten door de grafiek van f, de x-as en de y-as. Zie de figuur. Deze figuur is niet op schaal.$$, 'inline'),
  ('00886d3e-a85f-48a6-8912-932c5b8d1e7b', '9d61d7f2-fa1a-4dc9-8b33-e21e03930ba3', $$figuur: vlakdeel V$$,
   $$wiskunde-b-vwo-2021-iii-een-derdegraadsfunctie-context3.png$$,
   $$figuur: grafiek van f met het grijze vlakdeel V (niet op schaal)$$, 'inline'),
  ('76ad5429-4a90-4677-bded-d565bca7ac9e', '9d61d7f2-fa1a-4dc9-8b33-e21e03930ba3', $$V wordt gewenteld om de y-as$$,
   $$wiskunde-b-vwo-2021-iii-een-derdegraadsfunctie-context4.png$$,
   $$Vlakdeel V wordt gewenteld om de y-as. Zo ontstaat een omwentelingslichaam.$$, 'inline'),
  ('2e644be2-a7fb-4327-b444-cacb8649696e', '9d61d7f2-fa1a-4dc9-8b33-e21e03930ba3', $$punt P (horizontale raaklijn aan f) en punt Q (verticale raaklijn aan f^inv)$$,
   $$wiskunde-b-vwo-2021-iii-een-derdegraadsfunctie-context5.png$$,
   $$Op de grafiek van f ligt een punt P waarin de raaklijn aan de grafiek van f horizontaal is.
Op de grafiek van f^inv ligt een punt Q waarin de raaklijn aan de grafiek van f^inv verticaal is.$$, 'inline'),
  ('86dac481-ee51-4fcb-8664-6d0d07d706df', '9d61d7f2-fa1a-4dc9-8b33-e21e03930ba3', $$de lijn door P en Q snijdt de y-as in S$$,
   $$wiskunde-b-vwo-2021-iii-een-derdegraadsfunctie-context6.png$$,
