  ('ae6e1ab0-01ea-4da0-a63f-e6b89a85170c', 'a9356d64-e544-400a-8696-29a985f9efb4', 2,
   '[{"domain": "Differentiaal- en integraalrekening", "subdomain": "Technieken voor differentiëren"}, {"domain": "Goniometrische functies", "subdomain": "Goniometrische functies"}]'::jsonb,
