   '["raaklijn", "loodrecht snijden", "product richtingscoëfficiënten", "afgeleide", "goniometrische vergelijking", "exact berekenen"]'::jsonb,
   $$Exact bepalen van het aantal waarden waarvoor raaklijnen aan twee goniometrische grafieken loodrecht op elkaar staan.$$,
   $$wiskunde-b-vwo-2021-iii-spookje-vraag3.png$$, $$6p 3 Bereken exact het aantal waarden van p waarvoor de twee raaklijnen elkaar loodrecht snijden.$$, array['f2dfe897-4c9f-4e92-9968-75593f19702c', 'da64edf4-8e0c-4b8d-a8d8-2a2c2af5a095', '0c5f4372-0ef0-4631-8356-674137e5568b', 'bb9f67d3-082e-4484-8c9f-47cfe171f170', '65da860c-84d5-4e17-bcb0-f4819394d249']::uuid[]),
