   '["bepaalde integraal", "oppervlakte tussen twee grafieken", "primitieve", "sinus", "exact berekenen"]'::jsonb,
   $$Exact berekenen van de oppervlakte van een gebied tussen twee goniometrische grafieken met een integraal.$$,
